// Add a new error
error GameNotCancellable();

// Add this new function
function cancelGame(uint256 gameId) external {
    Game storage game = games[gameId];

    if (game.status != GameStatus.WAITING || msg.sender != game.player1) {
        revert GameNotCancellable();
    }

    uint256 stake = game.stake;

    // Delete game state before transfer
    delete games[gameId];

    if (stake > 0) {
        (bool success, ) = payable(msg.sender).call{value: stake}("");
        if (!success) revert TransferFailed(); // Re-use existing error
    }

    // It's good practice to emit an event for this action.
    // event GameCancelled(uint256 indexed gameId);
}

