    if (game.status != GameStatus.WAITING) revert GameNotJoinable(); // Default is WAITING (0), so this passes
    if (msg.value != uint256(game.stake)) revert IncorrectStake(msg.value, game.stake); // Default stake is 0, so this passes if msg.value is 0
    if (msg.sender == game.player1) revert SelfPlayNotAllowed(); // Default player1 is address(0), so this passes

